            {
                "problem": "The long '3,000,000,000 bp' text at C6 runs off the right edge of the frame (cut after 'bp') and sits on top of the cell circle / zoom ring at D4.",
                "solution": "Line 194: self.place_in_area(bp_text, 'B6', 'D6', scale_factor=0.7) — center the long string in the empty bottom band (row 6, columns B–D) below the cell circle (C3-E5), keeping its orange color #E8663C; at 0.7 scale the full string fits inside the frame with no overlap with the helix or ring.",
                "line_number": 194,
                "object_affected": "bp_text"
            },
            {
                "problem": "The counter at D6 is squeezed against the right margin and would collide with the relocated base-pair text in row 6.",
                "solution": "Line 197: self.place_at_grid(counter, 'E6', scale_factor=0.8) — place the counter one column to the right of the bp_text block (B6-D6), same row, so it stays within 1 grid unit of the text it counts while remaining fully on-screen and clear of the cell circle above.",
                "line_number": 197,
                "object_affected": "counter"
            },
            {
                "problem": "'Speed' (B4) and 'Accuracy' (B5) labels touch each other, rendering as 'SpeedAccuracy' with no separation.",
                "solution": "Line 294: self.place_in_area(acc_label, 'B5', 'B6', scale_factor=0.7) — shift the cyan (#3FC1D4) 'Accuracy' label half a column right and shrink it slightly, creating a clear gap from 'Speed' at B4 while staying directly above/within 1 grid unit of the shield at C5.",
                "line_number": 294,
                "object_affected": "acc_label"
            }
        ]
    }
}
